 to try as a backup to this one. kAllRegions if none.	{		'****',						// resourceID - the type of resource, may be '****' for wildcard		kVerHungaryOffset			// IDOffset - the offset to add to ID for resources that support this locale	},		// Direct Mappings - None	{ }};//--------------------------------------------------------------------------------------------------// Other resources//--------------------------------------------------------------------------------------------------resource 'CMNU' (mApple + kVerHungaryOffset,#if qNames"mApple",#endifpurgeable) {	mApple, textMenuProc, 0x7FFFFFFD, enabled, apple,	{		"A' ^0",	noIcon, noKey, noMark, plain, cAboutApp;	// The ^0 will be dynamically replaced with CurApName		"-",		noIcon, noKey, noMark, plain, nocommand	}};resource 'CMNU' (mFile + kVerHungaryOffset,#if qNames"mFile",#endifpurgeable){	mFile, textMenuProc, EnablingManagedByMacApp, enabled, "Irat",	{		"Új",				noIcon, "N",	noMark, plain, cNew;		"Nyiss",			noIcon, "O",	noMark, plain, cOpen;		"-",				noIcon, noKey,	noMark, plain, nocommand;		"Csukd be",			noIcon, "W",	noMark, plain, cClose;		"Mentsd",			noIcon, "S",	noMark, plain, cSave;		"Mentsd mint…",		noIcon, noKey,	noMark, plain, cSaveAs;		"Állítsd vissza",	noIcon, noKey,	noMark, plain, cRevert;		"-",				noIcon, noKey,	noMark, plain, nocommand;		"Lapbeállítás…",	noIcon, noKey,	noMark, plain, cPageSetup;		"Myomtasd",			noIcon, "P",	noMark, plain, cPrint;		"Nyomtass egyet",	noIcon, noKey,	noMark, plain, cPrintOne;		"-",				noIcon, noKey,	noMark, plain, nocommand;		"Lépj ki",			noIcon, "Q",	noMark, plain, cQuit	}};resource 'CMNU' (mEdit + kVerHungaryOffset,#if qNames"mEdit",#endifpurgeable){	mEdit, textMenuProc, EnablingManagedByMacApp, enabled, "Szerk",	{		"Mégse",				noIcon, "Z",	noMark, plain, cUndo;		"Mégis",				noIcon, "R",	noMark, plain, cRedo;		"-",					noIcon, noKey,	noMark, plain, nocommand;		"Vágd ki",				noIcon, "X",	noMark, plain, cCut;		"Másold",				noIcon, "C",	noMark, plain, cCopy;		"Toldd be",				noIcon, "V",	noMark, plain, cPaste;		"Töröld",				noIcon, noKey,	noMark, plain, cClear;		"Válaszd ki mind",		noIcon, "A",	noMark, plain, cSelectAll;		"-",					noIcon, noKey,	noMark, plain, nocommand;		"Mutasd a tıtáblát",	noIcon, noKey,	noMark, plain, cShowClipboard;	}};